choose.when:
select 

from PTL_SEC_POSITION A,
FIN_PRODUCT_TYPE B

	A.FINPROD_ID = B.FINPROD_ID

		and	A.PORTFOLIO_ID = #{portfolioId}


		and	A.SEC_ACCT_ID = #{secAcctId}


		and A.FINPROD_ID = #{finprodId}


		and A.CDATE >= #{startCdate,jdbcType=DATE}


		and A.CDATE <= #{endCdate,jdbcType=DATE}



		and A.HODING_TYPE = '02'


		and A.HODING_TYPE != '02'

select 

from 
	PTL_CASH_POSITION_FLOW C,
	STL_PAY_ORDERS E
left join TRD_PRODUCT_DEAL D on (D.TRADE_ID = E.TRADE_ID OR D.TOTLE_TRADE_ID = E.TRADE_ID)
left join PA_TRD_PRODUCT_DEAL F on (D.TRADE_ID = F.TRADE_ID)
left join WFL_TRD_PRODUCT_DEAL G on (G.TRADE_ID = E.TRADE_ID OR G.TOTLE_TRADE_ID = E.TRADE_ID)
left join WFL_PA_TRD_PRODUCT_DEAL H on (G.TRADE_ID = H.TRADE_ID)

	C.ORDER_ID = E.ORDER_ID

		and C.PORTFOLIO_ID = #{portfolioId1}


		and C.SEQNO LIKE CONCAT('%',CONCAT(#{seqno},'%'))


		and C.ACCT_ID LIKE CONCAT('%',CONCAT(#{acctId},'%'))


		and C.HODING_TYPE = #{cashType}


		and C.CDATE >= #{startCdate1,jdbcType=DATE}


		and C.CDATE <= #{endCdate1, jdbcType=DATE}


		and C.CCY = #{ccy}

choose.otherwise:
select 

from STL_PAY_ORDERS E,
TRD_PRODUCT_DEAL F,
PA_TRD_PRODUCT_DEAL G

	E.TRADE_ID = F.TRADE_ID AND F.TRADE_ID = G.TRADE_ID

		and E.ORDER_ID LIKE CONCAT('%',CONCAT(#{orderId},'%'))


		and E.ORDER_TYPE = #{orderType}


		and G.PA_BUSS_TYPE = #{bussType}


		and E.SETTLE_DATE >= #{startSettleDate,jdbcType=DATE}


		and E.SETTLE_DATE <= #{endSettleDate,jdbcType=DATE}


		and E.PORTFOLIO_ID = #{portfolioId}


		and E.PS = #{ps}
